// reproduce-pwa-gauge.js
// This standalone script will generate an HTML fragment containing just the PWA category gauge.
// 1. Install dependencies: npm install lighthouse jsdom
// 2. Place this file at your project root and run: node reproduce-pwa-gauge.js

const fs = require('fs');
const path = require('path');
const jsdom = require('jsdom');

// Lighthouse renderer modules
const Util = require('lighthouse/report/html/renderer/util.js');
const URL = require('lighthouse/lib/url-shim.js');
const DOM = require('lighthouse/report/html/renderer/dom.js');
const DetailsRenderer = require('lighthouse/report/html/renderer/details-renderer.js');
const CategoryRenderer = require('lighthouse/report/html/renderer/category-renderer.js');
const PwaCategoryRenderer = require('lighthouse/report/html/renderer/pwa-category-renderer.js');

// Load the HTML report template (contains <template> for gauge, etc.)
const TEMPLATE_FILE = require.resolve('lighthouse/report/html/templates.html');
const template = fs.readFileSync(TEMPLATE_FILE, 'utf8');

// Load a sample Lighthouse result (this comes from Lighthouse's own tests)
const sampleResultsOrig = require('lighthouse/lighthouse-core/test/results/sample_v2.json');

(async () => {
  // Prepare the DOM
  const {JSDOM} = jsdom;
  const dom = new JSDOM(template);
  const document = dom.window.document;

  // Expose globals that the renderers expect
  global.Util = Util;
  global.URL = URL;
  global.CategoryRenderer = CategoryRenderer;

  // Prepare the sample results
  const sampleResults = Util.prepareReportResult(sampleResultsOrig);
  const pwaCategory = sampleResults.categories.pwa;

  // Set up renderers
  const domHelper = new DOM(document);
  const detailsRenderer = new DetailsRenderer(domHelper);
  const pwaRenderer = new PwaCategoryRenderer(domHelper, detailsRenderer);

  // Render only the PWA category header (with gauge)
  const categoryElem = pwaRenderer.render(pwaCategory, sampleResults.categoryGroups);

  // Serialize and write to disk
  const wrapper = document.createElement('div');
  wrapper.appendChild(categoryElem);
  fs.writeFileSync(path.join(__dirname, 'pwa-category.html'), wrapper.innerHTML);
  console.log('Generated pwa-category.html — open in your browser to inspect the PWA gauge.');
})();
